using System;using System.Collections.Generic;using NUnit.Framework;using RealmRaiders.Modules.InfernalDefenseLayouts;using RealmRaiders.Modules.InfernalEncounters;
namespace RealmRaiders.Modules.InfernalFirstExpansionContent.Tests
{public sealed class InfernalFirstExpansionContentCatalogueTests
{
 [Test] public void Catalogue_PinsExactThreeRecipesAndOrderedPlacements(){AssertRecipe(0,StarterInfernalDefenseLayouts.AshenSpurId,"ashen.west-vent","ashen.hellhound","realmraiders.infernal-expansion.ashen-pack-vent","Ashen Pack Vent","ashen-pack-vent",new[]{new ExpectedHostile(StarterInfernalRaidPacingCatalogue.HellhoundArchetypeId,-1.8f,.8f),new ExpectedHostile(StarterInfernalRaidPacingCatalogue.HellhoundArchetypeId,1.8f,1.2f)},null,0f,0f,"TWO HELLHOUNDS GUARD THE ASHEN VENT.");AssertRecipe(1,StarterInfernalDefenseLayouts.CinderForkId,"cinder.north-vent","cinder.hellhound","realmraiders.infernal-expansion.cinder-snare-vent","Cinder Snare Vent","cinder-snare-vent",new[]{new ExpectedHostile(StarterInfernalRaidPacingCatalogue.HellhoundArchetypeId,0f,1.3f)},StarterInfernalRaidPacingCatalogue.FlameTrapContentId,0f,-.4f,"A HELLHOUND GUARDS THE CINDER SNARE.");AssertRecipe(2,StarterInfernalDefenseLayouts.EmberCircuitId,"ember.west-vent","ember.hellhound","realmraiders.infernal-expansion.brute-kiln-vent","Brute Kiln Vent","brute-kiln-vent",new[]{new ExpectedHostile(StarterInfernalRaidPacingCatalogue.InfernalBruteArchetypeId,0f,1.5f)},null,0f,0f,"AN INFERNAL BRUTE HOLDS THE EMBER VENT.");}
 [Test] public void Lookup_FailsClosedForInvalidForeignAndLaterSockets(){Reject(StarterInfernalFirstExpansionContent.FindExact(null,"ashen.west-vent"),InfernalFirstExpansionContentLookupStatus.LayoutIdInvalid);Reject(StarterInfernalFirstExpansionContent.FindExact(StarterInfernalDefenseLayouts.AshenSpurId,"Invalid Socket"),InfernalFirstExpansionContentLookupStatus.SocketIdInvalid);Reject(StarterInfernalFirstExpansionContent.FindExact("realmraiders.infernal-defense.unknown","socket.one"),InfernalFirstExpansionContentLookupStatus.LayoutUnknown);Reject(StarterInfernalFirstExpansionContent.FindExact(StarterInfernalDefenseLayouts.AshenSpurId,"ashen.east-vent"),InfernalFirstExpansionContentLookupStatus.SocketNotFirstAuthored);Reject(StarterInfernalFirstExpansionContent.FindExact(StarterInfernalDefenseLayouts.AshenSpurId,"ashen.unknown"),InfernalFirstExpansionContentLookupStatus.SocketUnknown);}
 [Test] public void Validate_RejectsChangedFactsAndUnsafeEvidence(){var r=StarterInfernalFirstExpansionContent.CinderSnareVent;var changed=new InfernalFirstExpansionContentRecipe(r.LayoutId,r.SocketId,"cinder.changed",r.SiteId,r.SiteName,r.SiteSignature,new[]{new InfernalExpansionHostilePlacement(StarterInfernalRaidPacingCatalogue.InfernalBruteArchetypeId,float.NaN,4f)},new InfernalExpansionHazardPlacement(StarterInfernalRaidPacingCatalogue.FlameTrapContentId,float.PositiveInfinity,-.4f,false,false),"CHANGED");var list=new List<InfernalFirstExpansionContentRecipe>{changed,StarterInfernalFirstExpansionContent.CinderSnareVent,StarterInfernalFirstExpansionContent.BruteKilnVent};var v=StarterInfernalFirstExpansionContent.Validate(list);Assert.That(v.IsValid,Is.False);Assert.That(v.Issues,Does.Contain(InfernalFirstExpansionContentValidationIssue.LayoutIdDuplicate));Assert.That(v.Issues,Does.Contain(InfernalFirstExpansionContentValidationIssue.SourceNodeMismatch));Assert.That(v.Issues,Does.Contain(InfernalFirstExpansionContentValidationIssue.HostileOffsetInvalid));Assert.That(v.Issues,Does.Contain(InfernalFirstExpansionContentValidationIssue.HazardOffsetInvalid));Assert.That(v.Issues,Does.Contain(InfernalFirstExpansionContentValidationIssue.HazardSemanticsInvalid));Assert.That(v.Issues,Does.Contain(InfernalFirstExpansionContentValidationIssue.ExactFactsMismatch));}
 [Test] public void Validate_RejectsOrderCardinalityAndDuplicateSite(){var a=StarterInfernalFirstExpansionContent.AshenPackVent;var reversed=new[]{a.Hostiles[1],a.Hostiles[0]};var changed=new InfernalFirstExpansionContentRecipe(a.LayoutId,a.SocketId,a.SourceNodeId,a.SiteId,a.SiteName,a.SiteSignature,reversed,null,a.Cue);var list=new List<InfernalFirstExpansionContentRecipe>{changed,StarterInfernalFirstExpansionContent.CinderSnareVent,StarterInfernalFirstExpansionContent.CinderSnareVent,StarterInfernalFirstExpansionContent.BruteKilnVent};var v=StarterInfernalFirstExpansionContent.Validate(list);Assert.That(v.IsValid,Is.False);Assert.That(v.Issues,Does.Contain(InfernalFirstExpansionContentValidationIssue.CatalogueCardinalityInvalid));Assert.That(v.Issues,Does.Contain(InfernalFirstExpansionContentValidationIssue.HostileOrderMismatch));Assert.That(v.Issues,Does.Contain(InfernalFirstExpansionContentValidationIssue.SiteIdDuplicate));Assert.That(v.Issues,Does.Contain(InfernalFirstExpansionContentValidationIssue.SiteSignatureDuplicate));}
 [Test] public void Validate_RejectsCatalogueReorderAndDoesNotMislabelChangedContentAsOrder(){var reordered=new List<InfernalFirstExpansionContentRecipe>{StarterInfernalFirstExpansionContent.CinderSnareVent,StarterInfernalFirstExpansionContent.AshenPackVent,StarterInfernalFirstExpansionContent.BruteKilnVent};var order=StarterInfernalFirstExpansionContent.Validate(reordered);Assert.That(order.Issues,Does.Contain(InfernalFirstExpansionContentValidationIssue.CatalogueOrderMismatch));var a=StarterInfernalFirstExpansionContent.AshenPackVent;var changed=new InfernalFirstExpansionContentRecipe(a.LayoutId,a.SocketId,a.SourceNodeId,a.SiteId,a.SiteName,a.SiteSignature,new[]{new InfernalExpansionHostilePlacement(StarterInfernalRaidPacingCatalogue.InfernalBruteArchetypeId,a.Hostiles[0].LocalX,a.Hostiles[0].LocalZ),a.Hostiles[1]},null,a.Cue);var content=StarterInfernalFirstExpansionContent.Validate(new List<InfernalFirstExpansionContentRecipe>{changed,StarterInfernalFirstExpansionContent.CinderSnareVent,StarterInfernalFirstExpansionContent.BruteKilnVent});Assert.That(content.Issues,Does.Contain(InfernalFirstExpansionContentValidationIssue.ExactFactsMismatch));var hasOrderMismatch=false;foreach(var issue in content.Issues)if(issue==InfernalFirstExpansionContentValidationIssue.HostileOrderMismatch){hasOrderMismatch=true;break;}Assert.That(hasOrderMismatch,Is.False);}
 [Test] public void Lookup_IsCachedAndListsAreSnapshotted(){var first=StarterInfernalFirstExpansionContent.FindExact(StarterInfernalDefenseLayouts.CinderForkId,"cinder.north-vent");var second=StarterInfernalFirstExpansionContent.FindExact(StarterInfernalDefenseLayouts.CinderForkId,"cinder.north-vent");var source=new List<InfernalExpansionHostilePlacement>{new InfernalExpansionHostilePlacement(StarterInfernalRaidPacingCatalogue.HellhoundArchetypeId,0f,1f)};var copy=new InfernalFirstExpansionContentRecipe(StarterInfernalDefenseLayouts.AshenSpurId,"ashen.west-vent","ashen.hellhound","realmraiders.site.copy","Copy","copy",source,null,"COPY");source.Clear();Assert.That(second.Recipe,Is.SameAs(first.Recipe));Assert.That(copy.Hostiles.Count,Is.EqualTo(1));Assert.That(StarterInfernalFirstExpansionContent.Validate(StarterInfernalFirstExpansionContent.All).IsValid,Is.True);}
 private static void AssertRecipe(int i,string layout,string socket,string source,string siteId,string name,string signature,ExpectedHostile[] hostiles,string hazard,float hazardX,float hazardZ,string cue){var r=StarterInfernalFirstExpansionContent.All[i];var found=StarterInfernalFirstExpansionContent.FindExact(layout,socket);Assert.That(r.LayoutId,Is.EqualTo(layout));Assert.That(r.SocketId,Is.EqualTo(socket));Assert.That(r.SourceNodeId,Is.EqualTo(source));Assert.That(r.SiteId,Is.EqualTo(siteId));Assert.That(r.SiteName,Is.EqualTo(name));Assert.That(r.SiteSignature,Is.EqualTo(signature));Assert.That(r.Cue,Is.EqualTo(cue));Assert.That(r.Hostiles.Count,Is.EqualTo(hostiles.Length));for(var n=0;n<hostiles.Length;n++){Assert.That(r.Hostiles[n].ContentId,Is.EqualTo(hostiles[n].ContentId));Assert.That(r.Hostiles[n].LocalX,Is.EqualTo(hostiles[n].LocalX));Assert.That(r.Hostiles[n].LocalZ,Is.EqualTo(hostiles[n].LocalZ));}Assert.That(r.Hazard==null,Is.EqualTo(hazard==null));if(r.Hazard!=null){Assert.That(r.Hazard.ContentId,Is.EqualTo(hazard));Assert.That(r.Hazard.LocalX,Is.EqualTo(hazardX));Assert.That(r.Hazard.LocalZ,Is.EqualTo(hazardZ));Assert.That(r.Hazard.IsBypassable,Is.True);Assert.That(r.Hazard.IsNonBlocking,Is.True);}Assert.That(found.Recipe,Is.SameAs(r));}
 private static void Reject(InfernalFirstExpansionContentLookupResult r,InfernalFirstExpansionContentLookupStatus s){Assert.That(r.Status,Is.EqualTo(s));Assert.That(r.Found,Is.False);Assert.That(r.Recipe,Is.Null);}
 private sealed class ExpectedHostile{public ExpectedHostile(string contentId,float localX,float localZ){ContentId=contentId;LocalX=localX;LocalZ=localZ;}public string ContentId{get;}public float LocalX{get;}public float LocalZ{get;}}
}}
